<script>
document.getElementById('cs-website-permissions').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button'),status=form.querySelector('[role="status"]'),values=new FormData(form),policy={};form.querySelectorAll('input[type="checkbox"]').forEach(input=>policy[input.name]=values.has(input.name));button.disabled=true;status.textContent='Saving website user permissions…';try{const response=await window.ClamShieldApiResponse.fetch(location.pathname,{method:'POST',credentials:'same-origin',body:new URLSearchParams({token:<?=json_encode($_SESSION['token']??'',JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,owner:<?=json_encode($data['context']['owner'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,action:'website-permissions-save',scope:form.dataset.scope,policy:JSON.stringify(policy)})});const result=await window.ClamShieldApiResponse.read(response,"Website permissions could not be saved");if(!response.ok||!result.ok)throw new Error(result.error||'Website permissions could not be saved');location.reload();}catch(error){status.textContent=error.message;button.disabled=false;}});
</script>
